(function () {
'use strict';
var cards, bar, countEl, resetBtn, searchInput, sortSel;
function readState() {
var st = { type: [], texture: [], color: [], room: [], q: '', sort: 'popular' };
document.querySelectorAll('.filters input[type=checkbox]:checked').forEach(function (c) {
st[c.dataset.group].push(c.value);
});
if (searchInput) st.q = searchInput.value.trim().toLowerCase();
if (sortSel) st.sort = sortSel.value;
return st;
}
function match(card, st) {
if (st.type.length && st.type.indexOf(card.dataset.type) === -1) return false;
if (st.texture.length && st.texture.indexOf(card.dataset.texture) === -1) return false;
if (st.color.length && !st.color.some(function (c) { return (card.dataset.color || '').split(',').indexOf(c) > -1; })) return false;
if (st.room.length && !st.room.some(function (c) { return (card.dataset.room || '').split(',').indexOf(c) > -1; })) return false;
if (st.q && (card.dataset.search || '').toLowerCase().indexOf(st.q) === -1) return false;
return true;
}
function apply(push) {
var st = readState();
var shown = 0;
var visible = [];
cards.forEach(function (c) {
var ok = match(c, st);
c.style.display = ok ? '' : 'none';
if (ok) { shown++; visible.push(c); }
});
var price = function (c) { return Number(c.dataset.price || 0); };
var pop = function (c) { return Number(c.dataset.pop || 0); };
visible.sort(function (a, b) {
if (st.sort === 'price-asc') return price(a) - price(b);
if (st.sort === 'price-desc') return price(b) - price(a);
return pop(b) - pop(a);
});
var parent = cards[0].parentNode;
visible.forEach(function (c) { parent.appendChild(c); });
cards.forEach(function (c) { if (visible.indexOf(c) === -1) parent.appendChild(c); });
if (countEl) countEl.textContent = 'Найдено решений: ' + shown;
var empty = document.querySelector('[data-catalog-empty]');
if (empty) empty.style.display = shown ? 'none' : '';
if (resetBtn) resetBtn.style.display = (st.type.length || st.texture.length || st.color.length || st.room.length || st.q) ? '' : 'none';
if (push !== false) {
var p = new URLSearchParams();
st.type.forEach(function (v) { p.append('type', v); });
st.texture.forEach(function (v) { p.append('texture', v); });
st.color.forEach(function (v) { p.append('color', v); });
st.room.forEach(function (v) { p.append('room', v); });
if (st.q) p.set('q', st.q);
if (st.sort !== 'popular') p.set('sort', st.sort);
var qs = p.toString();
history.replaceState(null, '', location.pathname + (qs ? '?' + qs : ''));
}
}
function restoreFromUrl() {
var p = new URLSearchParams(location.search);
['type', 'texture', 'color', 'room'].forEach(function (g) {
var vals = p.getAll(g);
if (!vals.length) return;
document.querySelectorAll('.filters input[data-group="' + g + '"]').forEach(function (c) {
c.checked = vals.indexOf(c.value) > -1;
});
});
if (p.get('q') && searchInput) searchInput.value = p.get('q');
if (p.get('sort') && sortSel) sortSel.value = p.get('sort');
}
function updateCounters() {
document.querySelectorAll('.filters input[type=checkbox]').forEach(function (c) {
var cnt = c.closest('.f-group').querySelector('.cnt');
if (!cnt) return;
var saved = c.checked;
c.checked = true;
var st = readState();
st[c.dataset.group] = [c.value]; 
var n = 0;
cards.forEach(function (card) { if (match(card, st)) n++; });
c.checked = saved;
cnt.textContent = n;
});
}
document.addEventListener('DOMContentLoaded', function () {
var scope = document.querySelector('[data-catalog-scope]') || document;
cards = Array.prototype.slice.call(scope.querySelectorAll('[data-card]'));
if (!cards.length) return;
bar = document.querySelector('[data-catalog-bar]');
countEl = document.querySelector('[data-catalog-count]');
resetBtn = document.querySelector('[data-filters-reset]');
searchInput = document.querySelector('[data-catalog-search]');
sortSel = document.querySelector('[data-catalog-sort]');
var filtersEl = document.querySelector('.filters');
if (!filtersEl) return; 
restoreFromUrl();
apply(false);
updateCounters();
filtersEl.addEventListener('change', function () { apply(); updateCounters(); });
if (searchInput) {
var t;
searchInput.addEventListener('input', function () { clearTimeout(t); t = setTimeout(function () { apply(); }, 180); });
}
if (sortSel) sortSel.addEventListener('change', function () { apply(); });
if (resetBtn) resetBtn.addEventListener('click', function () {
document.querySelectorAll('.filters input[type=checkbox]').forEach(function (c) { c.checked = false; });
if (searchInput) searchInput.value = '';
if (sortSel) sortSel.value = 'popular';
apply(); updateCounters();
});
var tog = document.querySelector('[data-filters-toggle]');
if (tog) tog.addEventListener('click', function () {
var f = document.querySelector('.filters');
var open = f.classList.toggle('open');
tog.setAttribute('aria-expanded', String(open));
});
});
})();